/// <summary>
/// designed by AVANADE
/// </summary>
[ExtensionOf(classStr(SalesQuotationCopying))]
final class AVASalesquotationCopyingCls_Extension
{

    private LogisticsDeliveryName       deliveryName;
    private LogisticsPostalAddressRecId deliveryAddress;
    private NoYes copyFromJournal;




}

Method.Source:
/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_salesQuotationCopyingContract">SalesQuotationCopyingContract</param>
protected void initializeParametersFromContract(SalesQuotationCopyingContract _salesQuotationCopyingContract)
{
    next initializeParametersFromContract(_salesQuotationCopyingContract);
    copyFromJournal = _salesQuotationCopyingContract.parmAVACopyFromJournal();

    recalculateAmount       = false;
}

/// <summary>
/// designed by AVANADE
/// </summary>
protected void deleteSalesQuotationLines()
{
    next deleteSalesQuotationLines();

    deliveryName    = this.salesQuotationTable.DeliveryName;
    deliveryAddress = this.salesQuotationTable.DeliveryPostalAddress;
}

/// <summary>
/// designed by AVANADE
/// </summary>
void copyHeader()
{
    SalesQuotationLine  salesQuotLine;
    AVASalesQuotationHasLines sqHasLines;
    DocuRef docuRef;

    if (deliveryName || deliveryAddress)
    {
        salesQuotationTable.DeliveryName       = deliveryName;
        salesQuotationTable.DeliveryPostalAddress   = deliveryAddress;
    }

    select firstonly RecId from salesQuotLine where salesQuotLine.QuotationId == salesQuotationTable.quotationId;
    if (salesQuotLine.RecId)
    {
        sqHasLines = AVASalesQuotationHasLines::find(salesQuotationTable.quotationid, true);
        if (!sqHasLines)
        {
            sqHasLines.SalesQuotationId = salesQuotationTable.quotationid;
            sqHasLines.insert();
        }
    }

    if (this.parmCopyFromJournal())
    {
        delete_from docuRef where docuRef.RefTableId == tableNum(salesQuotationTable)
            && docuRef.RefRecId == salesQuotationTable.recid;
    }
    next copyHeader();

}

/// <summary>
/// designed from AVA
/// </summary>
public void copy()
{
    SalesQuotationLine avaSQL;
    AVASalesQuotationHasLines sqHasLines;

    SysGlobalCache globalCache = ClassFactory.globalCache();
    globalCache.clear(strFmt("@NDX:NXAP1P2",curUserId(),classStr(SalesQuotationLineType)));
    select count(RecId) from avaSQL where avaSQL.QuotationId == salesQuotationTable.quotationid;
    if (avaSQL.RecId)
    {
        sqHasLines = AVASalesQuotationHasLines::find(salesQuotationTable.quotationid, true);
        if (!sqHasLines)
        {
            sqHasLines.SalesQuotationId = salesQuotationTable.quotationid;
            sqHasLines.insert();
        }
    }
    next copy();

    delete_from sqHasLines where sqHasLines.SalesQuotationId == salesQuotationTable.quotationid;

    globalCache.clear(strFmt("@NDX:NXAP1P2",curUserId(),classStr(SalesQuotationLineType)));
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_salesQuotationTable">_salesQuotationTable</param>
protected void updateSalesQuotationAfterCopying(SalesQuotationTable _salesQuotationTable)
{
    SalesQuotationLine      salesQuotationLineItemGrp;
    SalesQuotationLine      avaSalesQuotationLineLoc;

    while select count(Recid) from  salesQuotationLineItemGrp
            group by ItemId
            where salesQuotationLineItemGrp.QuotationId == _salesQuotationTable.QuotationId
    {
        if (salesQuotationLineItemGrp.RecId > 1 && salesQuotationLineItemGrp.ItemId)
        {
            ttsbegin;
            update_recordset avaSalesQuotationLineLoc
            setting KCS_MultipleItem = 'X'
            where avaSalesQuotationLineLoc.ItemId == salesQuotationLineItemGrp.itemId
            //&& avaSalesQuotationLineLoc.QuotationId == this.quotationId;
            && avasalesquotationlineloc.QuotationId == _salesQuotationTable.QuotationId;
            ttscommit;
        }
    }
    next updateSalesQuotationAfterCopying(_salesQuotationTable);
}
